#include <map>
#include <string>
#include <vector>

std::map<std::string, int> wordCounts(const std::vector<std::string>& words)
{
    std::map<std::string, int> counts{};
    for (const std::string& word : words)
    {
        ++counts[word];
    }
    return counts;
}

unitTests:
TEST("counts each word") { const auto c{ wordCounts({ "the", "cat", "and", "the", "hat", "the" }) }; CHECK_EQ(c.size(), 4u); CHECK_EQ(c.at("the"), 3); CHECK_EQ(c.at("cat"), 1); CHECK(!c.contains("dog")); }
TEST("a map keeps its keys sorted") { const auto c{ wordCounts({ "pear", "apple", "fig" }) }; std::string order; for (const auto& [word, n] : c) order += word + " "; CHECK_EQ(order, "apple fig pear "); }
TEST("empty") { CHECK(wordCounts({}).empty()); }

